export const handler=async(req,res)=>{
 try{
  const url=new URL(req.url,`http://${req.headers.host||'localhost'}`),routed=url.searchParams.get('melaaPath');
  if(routed&&/^(\/api\/|\/uploads\/)/.test(routed))url.pathname=routed;
  if(process.env.NODE_ENV==='production')res.setHeader('strict-transport-security','max-age=31536000; includeSubDomains');
  if(req.method!=='GET'&&req.headers.origin&&new URL(req.headers.origin).host!==req.headers.host)return err(res,403,'Cross-origin request denied');
 if(url.pathname.startsWith('/api/')){
   const sensitive=['/api/login','/api/register'].includes(url.pathname),ok=allowRate(req,sensitive?'auth':'api',sensitive?20:240,15*60*1000);
   if(!ok)return err(res,429,'Too many requests. Please wait and try again.');
   if(sensitive&&!await allowDurableRate(req,'auth',30,15*60*1000))return err(res,429,'Too many account requests. Please wait and try again.');
   return await routes(req,res,url);
  }
  if(req.method!=='GET')return err(res,405,'Method not allowed');
  if(url.pathname.startsWith('/uploads/')){
   const filename=decodeURIComponent(url.pathname.slice(9)),target=path.resolve(uploadsDir,filename);
   if(!target.startsWith(uploadsDir+path.sep))return err(res,403,'Forbidden');
   const asset=await db.prepare('SELECT owner_id,blob_url FROM media_assets WHERE filename=?').get(filename),approved=asset&&Boolean(await db.prepare("SELECT 1 FROM products WHERE image=? AND status='active' UNION SELECT 1 FROM posts WHERE media_url=? AND status='active' LIMIT 1").get(url.pathname,url.pathname)),viewer=await auth(req);
   if(!asset||!approved&&viewer?.role!=='admin'&&viewer?.id!==asset.owner_id)return err(res,404,'Media not found');
   if(asset.blob_url){
    const result=await getBlob(asset.blob_url,{access:'private'});
    if(!result||result.statusCode!==200)return err(res,404,'Media not found');
    res.writeHead(200,{...securityHeaders,'content-type':result.blob.contentType,'cache-control':'private, no-store'});
    return Readable.fromWeb(result.stream).pipe(res);
   }
   return serveFile(res,target,true);
  }
  const rel=url.pathname==='/'?'index.html':decodeURIComponent(url.pathname.slice(1)),target=path.resolve(root,'public',rel);
  if(!target.startsWith(path.join(root,'public')+path.sep))return err(res,403,'Forbidden');
  serveFile(res,target);
 }catch(e){console.error(e);if(!res.headersSent)err(res,e instanceof SyntaxError?400:500,process.env.NODE_ENV==='production'?'Request could not be completed':e.message||'Request failed');else res.end()}
};
if(!process.env.VERCEL&&process.env.MELAA_MIGRATE_ONLY!=='1')http.createServer(handler).listen(Number(process.env.PORT)||3000,'0.0.0.0',()=>console.log(`Melaa running at http://localhost:${process.env.PORT||3000}`));
